#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 1;
    for (int i = 0; i < n; i++) {
        int so;
        if (scanf("%d", &so) != 1) return 1;
        printf(so == 0 ? "timer\n" : "keyboard\n");
    }
    return 0;
}
